def caesar_cipher(text: str, shift: int) -> str:
    result = []
    for char in text:
        if 'a' <= char <= 'z':
            # Handle lowercase letters
            # ord('a') is the base offset (0-25)
            shifted_ord = ord('a') + (ord(char) - ord('a') + shift) % 26
            result.append(chr(shifted_ord))
